<div class="cardx">
  <div class="hd"><form class="d-flex gap-2 flex-wrap" method="get"><input class="fi" style="width:230px" name="q" value="<?= e($q) ?>" placeholder="Number, name, product...">
    <select class="fi" name="status" style="width:150px" onchange="this.form.submit()"><option value="">All status</option><?php foreach (demand_statuses() as $s): ?><option value="<?= $s ?>" <?= $st === $s ? 'selected' : '' ?>><?= ucfirst($s) ?></option><?php endforeach; ?></select><button class="btn-a2"><?= icon('search', 15) ?> Filter</button></form><span style="color:var(--mute)"><?= (int)$total ?> requests</span></div>
  <div class="table-responsive"><table class="tb"><thead><tr><th>Request</th><th>Product</th><th>Customer</th><th>Qty</th><th>Budget</th><th>Quote</th><th>Status</th><th></th></tr></thead><tbody>
  <?php if (!$rows): ?><tr><td colspan="8" style="text-align:center;padding:40px;color:var(--mute)">No demand requests.</td></tr><?php endif; foreach ($rows as $d): ?>
    <tr><td><a href="<?= site_url('admin/demands/view/' . $d->id) ?>"><b><?= e($d->demand_no) ?></b></a><div style="color:var(--mute);font-size:12px"><?= time_ago($d->created_at) ?></div></td><td><?= e($d->product_name) ?><div style="color:var(--mute);font-size:12px"><?= e(trim($d->size . ' ' . $d->color)) ?></div></td><td><?= e($d->name) ?><div style="color:var(--mute);font-size:12px"><?= e($d->phone) ?></div></td><td><?= (int)$d->qty ?></td><td><?= $d->budget ? money($d->budget) : '-' ?></td><td><?= $d->quote_price ? '<b>' . money($d->quote_price) . '</b>' : '-' ?></td><td><?= status_badge($d->status) ?></td><td style="text-align:right"><a class="btn-a2 btn-sm2" href="<?= site_url('admin/demands/view/' . $d->id) ?>">Manage</a></td></tr><?php endforeach; ?></tbody></table></div>
  <?php if ($pages > 1): ?><div class="bd d-flex justify-content-between" style="border-top:1px solid var(--line);padding:14px 22px"><span style="color:var(--mute)">Page <?= $page ?> of <?= $pages ?></span><div class="pager"><?php $qs = $_GET; for ($n = 1; $n <= $pages; $n++): $qs['page'] = $n; ?><?= $n == $page ? '<span class="cur">' . $n . '</span>' : '<a href="?' . http_build_query($qs) . '">' . $n . '</a>' ?><?php endfor; ?></div></div><?php endif; ?>
</div>
